package com.hbm.client.soldering;
import com.hbm.machine.soldering.*;import net.minecraft.nbt.CompoundTag;import net.minecraft.network.chat.Component;import net.minecraft.resources.ResourceLocation;import snownee.jade.api.*;import snownee.jade.api.config.IPluginConfig;
@WailaPlugin public final class SolderingJadePlugin implements IWailaPlugin {
 @Override public void register(IWailaCommonRegistration event){event.registerBlockDataProvider(Provider.INSTANCE,SolderingBlockEntity.class);event.registerBlockDataProvider(Provider.INSTANCE,SolderingPort.class);}@Override public void registerClient(IWailaClientRegistration event){event.registerBlockComponent(Provider.INSTANCE,SolderingBlock.class);}
 private enum Provider implements IServerDataProvider<BlockAccessor>,IBlockComponentProvider{INSTANCE;@Override public ResourceLocation getUid(){return SolderingContent.id("soldering_state");}@Override public void appendServerData(CompoundTag tag,BlockAccessor accessor){var tile=accessor.getBlockEntity();if(tile instanceof SolderingPort&&accessor.getBlockState().getBlock() instanceof SolderingBlock block){var pos=block.findCore(accessor.getLevel(),accessor.getPosition());tile=pos==null?null:accessor.getLevel().getBlockEntity(pos);}if(tile instanceof SolderingBlockEntity machine){tag.putLong("hbm:soldering_consumption",machine.consumption);tag.putBoolean("hbm:soldering_collision",machine.collisionPrevention);}}@Override public void appendTooltip(ITooltip tooltip,BlockAccessor accessor,IPluginConfig config){var tag=accessor.getServerData();if(!tag.contains("hbm:soldering_consumption"))return;tooltip.add(Component.translatable("jade.hbm.soldering.consumption",tag.getLong("hbm:soldering_consumption")));tooltip.add(Component.translatable("gui.hbm.soldering.collision",Component.translatable(tag.getBoolean("hbm:soldering_collision")?"gui.hbm.soldering.on":"gui.hbm.soldering.off")));}}
}
